INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Analyse > Analyse Tools
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind Analyse-Tools immer notwendig, um IT-Probleme zu identifizieren?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Analyse ist ebenfalls möglich"}, {"text": "Ja", "correct": false, "because": "Tools helfen, sind aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Analyse-Tools automatisch Probleme beheben, ohne menschliches Eingreifen?', 2, '[{"text": "Nein", "correct": true, "because": "Tools diagnostizieren, Behebung oft manuell"}, {"text": "Ja", "correct": false, "because": "Automatische Behebung ist selten vollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, mit Analyse-Tools sowohl Hardware- als auch Softwareprobleme zu untersuchen?', 2, '[{"text": "Ja", "correct": true, "because": "Viele Tools decken beide Bereiche ab"}, {"text": "Nein", "correct": false, "because": "Tools sind oft vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Analyse-Tools ständig aktualisiert werden, um effektiv zu bleiben?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Probleme erfordern aktuelle Versionen"}, {"text": "Nein", "correct": false, "because": "Updates verbessern Effektivität"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Analyse-Tools ohne Zugriff auf Systemdaten sinnvoll genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Daten sind Grundlage der Analyse"}, {"text": "Ja", "correct": false, "because": "Ohne Daten fehlt die Basis"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Analyse-Tool wird häufig für die Untersuchung von Netzwerkverkehr verwendet?', 3, '[{"text": "Wireshark", "correct": true, "because": "Spezialisiert auf Paketanalyse"}, {"text": "Notepad", "correct": false, "because": "Nur ein Editor"}, {"text": "Excel", "correct": false, "because": "Für Tabellen, nicht Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei der Analyse von Systemprotokollen unter Linux?', 2, '[{"text": "logwatch", "correct": true, "because": "Analysiert Log-Dateien"}, {"text": "grep", "correct": false, "because": "Nur Textsuche, keine Analyse"}, {"text": "nano", "correct": false, "because": "Texteditor, keine Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Analyse-Tools in der IT?', 2, '[{"text": "Identifikation von Problemursachen", "correct": true, "because": "Diagnose ist Kernfunktion"}, {"text": "Erhöhung der Systemkomplexität", "correct": false, "because": "Nicht gewünscht"}, {"text": "Reduktion der Benutzeranzahl", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch den Einsatz veralteter Analyse-Tools entstehen?', 3, '[{"text": "Fehlende Erkennung neuer Probleme", "correct": true, "because": "Tools nicht auf dem neuesten Stand"}, {"text": "Schnellere Analyse", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Updates", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Analyse-Tool wird oft für die Performance-Überwachung von Servern genutzt?', 2, '[{"text": "Nagios", "correct": true, "because": "Überwacht Systemleistung"}, {"text": "Photoshop", "correct": false, "because": "Für Grafik, nicht Analyse"}, {"text": "Word", "correct": false, "because": "Für Texte, nicht Performance"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bieten Analyse-Tools typischerweise?', 4, '[{"text": "Datenvisualisierung", "correct": true, "because": "Erleichtert Interpretation"}, {"text": "Protokollanalyse", "correct": true, "because": "Untersucht Logs"}, {"text": "Echtzeitüberwachung", "correct": true, "because": "Erkennt aktuelle Probleme"}, {"text": "Grafikdesign", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Analyse-Tools sind für Netzwerkprobleme geeignet?', 3, '[{"text": "Wireshark", "correct": true, "because": "Paketanalyse"}, {"text": "Ping", "correct": true, "because": "Testet Erreichbarkeit"}, {"text": "Nmap", "correct": true, "because": "Scant Netzwerke"}, {"text": "Paint", "correct": false, "because": "Für Zeichnungen, nicht Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Analyse-Tools bei der Problemdiagnose?', 4, '[{"text": "Schnellere Fehlererkennung", "correct": true, "because": "Automatisierte Prozesse"}, {"text": "Detaillierte Berichte", "correct": true, "because": "Genauere Einsichten"}, {"text": "Reduzierter manueller Aufwand", "correct": true, "because": "Effizienzsteigerung"}, {"text": "Geringere Hardwarekosten", "correct": false, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können beim Einsatz von Analyse-Tools auftreten?', 3, '[{"text": "Falsche Konfiguration", "correct": true, "because": "Liefert ungenaue Ergebnisse"}, {"text": "Fehlende Schulung", "correct": true, "because": "Erschwert Nutzung"}, {"text": "Begrenzte Kompatibilität", "correct": true, "because": "Nicht für alle Systeme geeignet"}, {"text": "Zu schnelle Analyse", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Daten können Analyse-Tools untersuchen?', 3, '[{"text": "Systemprotokolle", "correct": true, "because": "Zeigen Ereignisse"}, {"text": "Netzwerkpakete", "correct": true, "because": "Für Kommunikation"}, {"text": "Leistungsmetriken", "correct": true, "because": "Bewerten Performance"}, {"text": "Büropläne", "correct": false, "because": "Nicht technisch relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Analyse-Tools können die Ursachen von Problemen aufzeigen. b) Alle Analyse-Tools sind kostenlos verfügbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ursachen ja, Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wireshark ist ein Tool zur Netzwerkanalyse. b) Analyse-Tools ersetzen menschliche Expertise vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wireshark ja, Expertise nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Analyse-Tools können Echtzeitdaten liefern. b) Tools sind immer plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Echtzeit ja, Plattform variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Analyse-Tools können bei der Fehlersuche Zeit sparen. b) Jedes Tool ist für alle Problemarten geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeit ja, Spezialisierung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Nagios kann Systemausfälle überwachen. b) Analyse-Tools benötigen keine Installation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nagios ja, Installation meist nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

